      await logAction('create', 'tax_exemption', Number(info.lastInsertRowid), `إعفاء ضريبي ${exemption_type} ${amount} لموظف ${employee_id} ${status === 'verified' ? '(مُوثَّق)' : '(قيد التوثيق)'}`);
